{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    dist_map = {}
    for u, v, d in dist_list:
        key = tuple(sorted((u, v)))
        dist_map[key] = d
    n = len(nodes)
    edges = []
    for i in range(n):
        u = nodes[i]
        cu = core[u]
        for j in range(i+1, n):
            v = nodes[j]
            key = tuple(sorted((u, v)))
            d = dist_map.get(key)
            if d is None:
                raise ValueError(f'Missing distance between {u} and {v}')
            mutual = max(cu, core[v], d)
            edges.append((mutual, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    edges_needed = n - 1
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == edges_needed:
                break
    if len(mst_edges) != edges_needed:
        raise ValueError('Graph is disconnected, cannot form MST')
    mst_edges.sort(key=lambda x: (x[2], x[0], x[1]))
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"}
